import { describe, it, expect } from 'vitest';
import git from 'isomorphic-git';
import {
  createTestContext,
  recordEvent,
  recordStateTransition,
  replayEvents,
  getDatabase,
  insertNode,
  HiveContext,
  Node,
} from '@hive/core';

const branch = 'hive-test';
async function bootstrap(): Promise<{ ctx: HiveContext; dir: string }> {
  const dir = '/test-repo';
  const ctx = await createTestContext(dir);
  ctx.fs.mkdirSync(dir, { recursive: true });
  ctx.fs.mkdirSync(`${dir}/.hive`, { recursive: true });
  await git.init({ fs: ctx.fs as any, dir, defaultBranch: 'main' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.name', value: 'Test User' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.email', value: 'test@example.com' });
  ctx.fs.writeFileSync(`${dir}/README.md`, '# Test');
  await git.add({ fs: ctx.fs as any, dir, filepath: 'README.md' });
  await git.commit({ fs: ctx.fs as any, dir, message: 'Initial commit',
    author: { name: 'Test User', email: 'test@example.com' } });
  await git.branch({ fs: ctx.fs as any, dir, ref: branch });
  return { ctx, dir };
}
async function addNode(ctx: HiveContext, title: string): Promise<string> {
  const id = await recordEvent(ctx, { type: 'add', nodeType: 'decision', content: title, confidence: 90 }, branch);
  const db = getDatabase(ctx);
  const now = new Date().toISOString();
  const node: Node = { change_id: id, branch, node_type: 'decision', title, status: 'pending', created_at: now, updated_at: now };
  insertNode(db, node);
  return id;
}

describe('recordStateTransition status survives incremental replay', () => {
  it('applies the completed status when the transition commit is pulled through the warm-db incremental path', async () => {
    const { ctx } = await bootstrap();
    const nodeId = await addNode(ctx, 'Ship it');
    const db = getDatabase(ctx);

    // Watermark currently points at the add commit (before any transition exists).
    const before = db.prepare('SELECT last_synced_git_hash AS h FROM sync_state WHERE branch = ?')
      .get(branch) as { h: string };

    // The ONLY way the CLI writes a status change: recordStateTransition.
    // This creates the commit whose body carries `new_value: completed` and no `status:` key.
    await recordStateTransition(ctx, nodeId, 'status', 'completed', branch);

    // Simulate pulling that commit onto a machine whose db already knows the node but
    // not the transition: remove the rows recordStateTransition wrote directly, and rewind
    // the watermark so replayEvents takes the incremental (getCommitsSince) path.
    db.prepare('DELETE FROM state_transitions WHERE branch = ?').run(branch);
    db.prepare('DELETE FROM state_refs WHERE branch = ?').run(branch);
    db.prepare('UPDATE sync_state SET last_synced_git_hash = ? WHERE branch = ?').run(before.h, branch);

    // Incremental replay of the new transition commit.
    await replayEvents(ctx, branch);

    // The status change SHOULD have been materialised as a transition to 'completed'.
    const transition = db.prepare(
      'SELECT new_value AS new_value FROM state_transitions WHERE node_id = ? AND branch = ?'
    ).get(nodeId) as { new_value: string } | undefined;

    expect(transition?.new_value).toBe('completed');
  });
});
